SELECT "investor_name" AS "investor_name", "investor_gp_id" AS "investor_id", "product" AS "product", SUM(TRY_CAST("order_demand_qty" AS DOUBLE)) AS "total_demand" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" IN (__P_f0_0__, __P_f0_1__) AND UPPER("deal_name") LIKE UPPER(__P_f1__) GROUP BY "investor_name", "investor_gp_id", "product" ORDER BY "total_demand" DESC LIMIT 5
